    /**
     * @return array<string, string>
     */
    public static function labels(): array
    {
        return array_map(
            static fn (array $icon): string => $icon['label'],
            self::ICONS,
        );
    }

    /**
     * @return array<int, string>
     */
    public static function names(): array
    {
        return array_keys(self::ICONS);
    }

    public static function render(?string $name, int $size = 24): HtmlString
    {
        $name = isset(self::ICONS[$name ?? '']) ? $name : 'utensils';
        $strokeWidth = $name === 'hookah' ? '1.2' : '2';

        return new HtmlString(
            '<svg data-icon="'.$name.'" width="'.$size.'" height="'.$size.'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="'.$strokeWidth.'" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
                .self::ICONS[$name]['svg']
                .'</svg>',
        );
    }

    public static function paths(string $name): HtmlString
    {
        $name = isset(self::ICONS[$name]) ? $name : 'utensils';

        return new HtmlString(self::ICONS[$name]['svg']);
    }
}
